bool SemanticAnalyzer::resolveBaseQualifier(const Expression& receiver,
                                           const Expression*& root,
                                           const ClassDeclaration*& view,
                                           std::vector<std::string>& path) {
    std::vector<std::string> reversed;
    const Expression* cursor = &receiver;
    while (cursor->kind == ExpressionKind::Member) {
        reversed.push_back(cursor->value);
        cursor = cursor->left.get();
    }
    if (reversed.empty()) return false;
    root = cursor;
    std::string rootType = analyzeExpression(*root);
    const auto found = classes_.find(rootType);
    if (found == classes_.end()) return false;
    view = found->second;
    for (auto name = reversed.rbegin(); name != reversed.rend(); ++name) {
        const auto base = std::find(view->baseClassNames.begin(),
                                    view->baseClassNames.end(), *name);
        if (base == view->baseClassNames.end()) return false;
        const auto baseClass = classes_.find(*name);
        if (baseClass == classes_.end()) return false;
        path.push_back(*name);
        view = baseClass->second;
    }
    return true;
}

std::string SemanticAnalyzer::analyzeExpression(const Expression& expression) {
    switch (expression.kind) {
    case ExpressionKind::Integer: {
        std::int32_t value = 0;
        const auto* begin = expression.value.data();
        const auto* end = begin + expression.value.size();
        const auto parsed = std::from_chars(begin, end, value);
        if (parsed.ec != std::errc{} || parsed.ptr != end) {
            throw DiagnosticError(expression.location,
                                  "integer literal is outside the signed 32-bit range");
        }
        return "int";
    }
    case ExpressionKind::String:
        return "string";
    case ExpressionKind::Null:
        return "null";
    case ExpressionKind::Identifier: {
        const auto index = findSymbolIndex(expression.value);
        if (index != symbols_.size()) {
            if (!symbols_[index].initialized) {
                throw DiagnosticError(expression.location,
                                      "variable '" + expression.value + "' may be uninitialized");
            }
            return symbols_[index].type;
        }
        if (currentClass_ != nullptr) {
            if (countFields(*currentClass_, expression.value) != 0 &&
                accessibleMemberCount(*currentClass_, expression.value, false) == 0) {
                throw DiagnosticError(expression.location,
                                      "field '" + expression.value +
                                          "' is not accessible in this class");
            }
            if (countFields(*currentClass_, expression.value) > 1) {
                throw DiagnosticError(expression.location,
                                      "ambiguous inherited field '" + expression.value +
                                          "'; qualify it through a base class");
            }
            if (const auto* field = findField(*currentClass_, expression.value)) {
                if (!memberAccessible(*currentClass_, expression.value, false)) {
                    throw DiagnosticError(expression.location,
                                          "field '" + expression.value +
                                              "' is not accessible in this class");
                }
                return field->type;
            }
        }
        throw DiagnosticError(expression.location,
                              "undefined variable '" + expression.value + "' or field");
    }
    case ExpressionKind::Member: {
        const Expression* root = nullptr;
        const ClassDeclaration* owner = nullptr;
        std::vector<std::string> path;
        if (!resolveBaseQualifier(*expression.left, root, owner, path)) {
            const auto receiverType = analyzeExpression(*expression.left);
            owner = findClass(receiverType, expression.location);
        }
        const auto matches = countFields(*owner, expression.value);
        const auto accessibleMatches = accessibleMemberCount(*owner, expression.value, false);
        if (accessibleMatches > 1) {
            throw DiagnosticError(expression.location,
                                  "ambiguous inherited field '" + expression.value +
                                      "'; qualify it through a base class");
        }
        const auto& accessOwner = path.empty() ? *owner : *classes_.at(analyzeExpression(*root));
        if (matches != 0 &&
            (accessibleMatches == 0 ||
             (!path.empty() && !basePathAccessible(accessOwner, path)))) {
            throw DiagnosticError(expression.location,
                                  "field '" + expression.value +
                                      "' is not accessible through this inheritance path");
        }
        if (const auto* field = findField(*owner, expression.value)) {
            return field->type;
        }
        throw DiagnosticError(expression.location,
                              "class '" + owner->name + "' has no field '" + expression.value + "'");
    }
    case ExpressionKind::ConstructorCall: {
        const auto* owner = findClass(expression.value, expression.location);
        const MethodDeclaration* constructor = nullptr;
        for (const auto& method : owner->methods) {
            if (method.constructor) {
                constructor = &method;
                break;
            }
        }
        if (constructor != nullptr &&
            !memberAccessible(*owner, constructor->name, true)) {
            throw DiagnosticError(expression.location,
                                  "constructor for class '" + owner->name +
                                      "' is not accessible here");
        }
        if (constructor == nullptr) {
            if (!expression.arguments.empty()) {
                throw DiagnosticError(expression.location,
                                      "class '" + owner->name + "' has no constructor");
            }
            return owner->name;
        }
        if (constructor->parameters.size() != expression.arguments.size()) {
            throw DiagnosticError(expression.location,
                                  "constructor argument count does not match class '" + owner->name + "'");
        }
        for (std::size_t index = 0; index < expression.arguments.size(); ++index) {
            const auto argumentType = analyzeExpression(*expression.arguments[index]);
            if (!isAssignable(constructor->parameters[index].type, argumentType) &&
                !(argumentType == "null" &&
                  classes_.find(constructor->parameters[index].type) != classes_.end())) {
                throw DiagnosticError(expression.arguments[index]->location,
                                      "constructor argument type does not match parameter '" +
                                          constructor->parameters[index].name + "'");
            }
        }
        return owner->name;
    }
    case ExpressionKind::Call: {
        if (expression.left->kind != ExpressionKind::Member) {
            throw DiagnosticError(expression.location, "only object method calls are supported");
        }
        const auto& target = *expression.left;
        const Expression* root = nullptr;
        const ClassDeclaration* owner = nullptr;
        std::vector<std::string> basePath;
        const bool qualified =
            resolveBaseQualifier(*target.left, root, owner, basePath);
        if (!qualified) {
            const auto receiverType = analyzeExpression(*target.left);
            owner = findClass(receiverType, target.location);
        }
        if (target.value == "destroy") {
            if (qualified) {
                throw DiagnosticError(target.location,
                                      "qualified destructor calls are not supported");
            }
            const auto findDestructor = [this](const auto& self,
                                               const ClassDeclaration& declaration)
                -> const MethodDeclaration* {
                for (const auto& candidate : declaration.methods) {
                    if (candidate.destructor) return &candidate;
                }
                for (const auto& baseName : declaration.baseClassNames) {
                    const auto base = classes_.find(baseName);
                    if (base != classes_.end()) {
                        if (const auto* inherited = self(self, *base->second))
                            return inherited;
                    }
                }
                return nullptr;
            };
            const auto* destructor = findDestructor(findDestructor, *owner);
            if (destructor == nullptr) {
                throw DiagnosticError(target.location,
                                      "class '" + owner->name + "' has no destructor");
            }
            if (accessibleMemberCount(*owner, "destroy", true) == 0) {
                throw DiagnosticError(target.location,
                                      "destructor for class '" + owner->name +
                                          "' is not accessible here");
            }
            if (!expression.arguments.empty()) {
                throw DiagnosticError(expression.location, "destructor takes no arguments");
            }
            std::cerr << target.location.file << ":" << target.location.line << ":"
                      << target.location.column
                      << ": warning: explicit destructor call does not reclaim the object\n";
            return "void";
        }
        const auto methodMatches = countMethods(*owner, target.value);
        const auto accessibleMethods = accessibleMemberCount(*owner, target.value, true);
        if (accessibleMethods > 1) {
            throw DiagnosticError(target.location,
                                  "ambiguous inherited method '" + target.value +
                                      "'; qualify it through a base class");
        }
        const auto& accessOwner =
            basePath.empty() ? *owner : *classes_.at(analyzeExpression(*root));
        if (methodMatches != 0 &&
            (accessibleMethods == 0 ||
             (!basePath.empty() && !basePathAccessible(accessOwner, basePath)))) {
            throw DiagnosticError(target.location,
                                  "method '" + target.value +
                                      "' is not accessible through this inheritance path");
        }
        const auto* method = findMethod(*owner, target.value);
        if (method == nullptr) {
            throw DiagnosticError(target.location,
                                  "class '" + owner->name + "' has no method '" + target.value + "'");
        }
        if (method->parameters.size() != expression.arguments.size()) {
            throw DiagnosticError(expression.location,
                                  "method '" + target.value + "' argument count mismatch");
        }
        for (std::size_t index = 0; index < expression.arguments.size(); ++index) {
            const auto argumentType = analyzeExpression(*expression.arguments[index]);
            if (!isAssignable(method->parameters[index].type, argumentType) &&
                !(argumentType == "null" &&
                  classes_.find(method->parameters[index].type) != classes_.end())) {
                throw DiagnosticError(expression.arguments[index]->location,
                                      "method argument type does not match parameter '" +
                                          method->parameters[index].name + "'");
            }
        }
        return method->returnType;
    }
    case ExpressionKind::Unary:
        if (analyzeExpression(*expression.left) != "int") {
            throw DiagnosticError(expression.location, "unary operator requires an int operand");
        }
        return "int";
    case ExpressionKind::Binary: {
        const auto left = analyzeExpression(*expression.left);
        const auto right = analyzeExpression(*expression.right);
        const auto& operation = expression.value;
        if (operation == "==" || operation == "!=") {
            if (left == "string" && right == "string") {
                throw DiagnosticError(expression.location,
                                      "string equality is not implemented in this prototype");
            }
            if (left != right) {
                throw DiagnosticError(expression.location, "comparison operands must be matching ints");
            }
            return "int";
        }
        if (left != "int" || right != "int") {
            throw DiagnosticError(expression.location,
                                  "operator '" + operation + "' requires int operands");
        }
        return "int";
    }
    }
    throw DiagnosticError(expression.location, "invalid expression");
}

std::string SemanticAnalyzer::analyzeLValue(const Expression& expression) {
    if (expression.kind == ExpressionKind::Identifier) {
        const auto index = findSymbolIndex(expression.value);
        if (index != symbols_.size()) {
            return symbols_[index].type;
        }
        if (currentClass_ != nullptr) {
            if (countFields(*currentClass_, expression.value) != 0 &&
                accessibleMemberCount(*currentClass_, expression.value, false) == 0) {
                throw DiagnosticError(expression.location,
                                      "field '" + expression.value +
                                          "' is not accessible in this class");
            }
            if (countFields(*currentClass_, expression.value) > 1) {
                throw DiagnosticError(expression.location,
                                      "ambiguous inherited field '" + expression.value +
                                          "'; qualify it through a base class");
            }
            if (const auto* field = findField(*currentClass_, expression.value)) {
                if (!memberAccessible(*currentClass_, expression.value, false)) {
                    throw DiagnosticError(expression.location,
                                          "field '" + expression.value +
                                              "' is not accessible in this class");
                }
                return field->type;
            }
        }
        throw DiagnosticError(expression.location,
                              "undefined variable '" + expression.value + "' or field");
    }
    if (expression.kind == ExpressionKind::Member) {
        const Expression* root = nullptr;
        const ClassDeclaration* owner = nullptr;
        std::vector<std::string> path;
        if (!resolveBaseQualifier(*expression.left, root, owner, path)) {
            const auto receiverType = analyzeExpression(*expression.left);
            owner = findClass(receiverType, expression.location);
        }
        const auto matches = countFields(*owner, expression.value);
        const auto accessibleMatches = accessibleMemberCount(*owner, expression.value, false);
        if (accessibleMatches > 1) {
            throw DiagnosticError(expression.location,
                                  "ambiguous inherited field '" + expression.value +
                                      "'; qualify it through a base class");
        }
        const auto& accessOwner = path.empty() ? *owner : *classes_.at(analyzeExpression(*root));
        if (matches != 0 &&
            (accessibleMatches == 0 ||
             (!path.empty() && !basePathAccessible(accessOwner, path)))) {
            throw DiagnosticError(expression.location,
                                  "field '" + expression.value +
                                      "' is not accessible through this inheritance path");
        }
        if (const auto* field = findField(*owner, expression.value)) {
            return field->type;
        }
        throw DiagnosticError(expression.location,
                              "class '" + owner->name + "' has no field '" + expression.value + "'");
    }
    throw DiagnosticError(expression.location, "assignment target must be a variable or object field");
}

